@Test
public void updateMessages() throws Exception {
    String messageId = "1";
    String content = "{\"message\": \"trying out Elasticsearch\",\"field\":\"Should be unchanged\"}";
    testee.indexMessage(messageId, content);
    embeddedElasticSearch.awaitForElasticSearch();
    testee.updateMessages(Lists.newArrayList(new ElasticSearchIndexer.UpdatedRepresentation(messageId, "{\"message\": \"mastering out Elasticsearch\"}")));
    embeddedElasticSearch.awaitForElasticSearch();
    try (Client client = node.client()) {
        SearchResponse searchResponse = client.prepareSearch(INDEX_NAME.getValue()).setTypes(TYPE_NAME.getValue()).setQuery(QueryBuilders.matchQuery("message", "mastering")).get();
        assertThat(searchResponse.getHits().getTotalHits()).isEqualTo(1);
    }
    try (Client client = node.client()) {
        SearchResponse searchResponse = client.prepareSearch(INDEX_NAME.getValue()).setTypes(TYPE_NAME.getValue()).setQuery(QueryBuilders.matchQuery("field", "unchanged")).get();
        assertThat(searchResponse.getHits().getTotalHits()).isEqualTo(1);
    }
}

