@Test
public void otherAttachmentsShouldBeenIndexedWhenOneOfThemCannotBeParsed() throws Exception {
    //Given
    MailboxMessage mailboxMessage = mock(MailboxMessage.class);
    TestId mailboxId = TestId.of(1);
    when(mailboxMessage.getMailboxId()).thenReturn(mailboxId);
    when(mailboxMessage.getFullContent()).thenReturn(new ByteArrayInputStream(IOUtils.toByteArray(ClassLoader.getSystemResourceAsStream("eml/emailWith3Attachments.eml"))));
    when(mailboxMessage.createFlags()).thenReturn(new Flags());
    when(mailboxMessage.getUid()).thenReturn(MESSAGE_UID);
    TextExtractor textExtractor = mock(TextExtractor.class);
    when(textExtractor.extractContent(any(), any(), any())).thenReturn(new ParsedContent("first attachment content", ImmutableMap.of())).thenThrow(new RuntimeException("second cannot be parsed")).thenReturn(new ParsedContent("third attachment content", ImmutableMap.of()));
    // When
    IndexableMessage indexableMessage = IndexableMessage.from(mailboxMessage, ImmutableList.of(new MockMailboxSession("username").getUser()), textExtractor, ZoneId.of("Europe/Paris"), IndexAttachments.YES);
    // Then
    assertThat(indexableMessage.getText()).contains("first attachment content");
    assertThat(indexableMessage.getText()).contains("third attachment content");
}

