@Test
public void testShouldNotAddExtensionsWithEncodingBodyStructure() throws Exception {
    FetchResponse message = new FetchResponse(100, flags, MessageUid.of(72), null, null, null, null, null, stubStructure, null);
    final Map<String, String> parameters = new HashMap<String, String>();
    parameters.put("CHARSET", "US-ASCII");
    final List<String> parameterList = new ArrayList<String>();
    parameterList.add("CHARSET");
    parameterList.add("US-ASCII");
    context.checking(new Expectations() {

        {
            final long octets = 2279L;
            final long lines = 48L;
            allowing(stubStructure).getMediaType();
            will(returnValue("TEXT"));
            allowing(stubStructure).getSubType();
            will(returnValue("HTML"));
            allowing(stubStructure).getOctets();
            will(returnValue(octets));
            allowing(stubStructure).getLines();
            will(returnValue(lines));
            allowing(stubStructure).getParameters();
            will(returnValue(parameterList));
            allowing(stubStructure).getEncoding();
            will(returnValue("7BIT"));
            ignoring(stubStructure);
        }
    });
    final FakeImapSession fakeImapSession = new FakeImapSession();
    encoder.doEncode(message, composer, fakeImapSession);
    assertEquals("* 100 FETCH (FLAGS (\\Deleted) BODYSTRUCTURE (\"TEXT\" \"HTML\" (\"CHARSET\" \"US-ASCII\") \"\" \"\" \"7BIT\" 2279 48) UID 72)\r\n", writer.getString());
}

