@Test
public void serviceShouldSendMultipartMailToTheSender() throws Exception {
    FakeMailetConfig mailetConfig = FakeMailetConfig.builder().mailetName(MAILET_NAME).mailetContext(fakeMailContext).build();
    dsnBounce.init(mailetConfig);
    MailAddress senderMailAddress = new MailAddress("sender@domain.com");
    MimeMessage mimeMessage = new MimeMessage(Session.getDefaultInstance(new Properties()));
    mimeMessage.setText("My content");
    FakeMail mail = FakeMail.builder().sender(senderMailAddress).mimeMessage(mimeMessage).name(MAILET_NAME).recipient(new MailAddress("recipient@domain.com")).lastUpdated(DateTime.parse("2016-09-08T14:25:52.000Z").toDate()).build();
    dsnBounce.service(mail);
    List<SentMail> sentMails = fakeMailContext.getSentMails();
    assertThat(sentMails).hasSize(1);
    SentMail sentMail = sentMails.get(0);
    assertThat(sentMail.getSender()).isNull();
    assertThat(sentMail.getRecipients()).containsOnly(senderMailAddress);
    MimeMessage sentMessage = sentMail.getMsg();
    assertThat(sentMessage.getContentType()).contains("multipart/report;");
    assertThat(sentMessage.getContentType()).contains("report-type=delivery-status");
}

@Test
public void serviceShouldSendMultipartMailContainingTextPart() throws Exception {
    FakeMailetConfig mailetConfig = FakeMailetConfig.builder().mailetName(MAILET_NAME).mailetContext(fakeMailContext).build();
    dsnBounce.init(mailetConfig);
    MailAddress senderMailAddress = new MailAddress("sender@domain.com");
    MimeMessage mimeMessage = new MimeMessage(Session.getDefaultInstance(new Properties()));
    mimeMessage.setText("My content");
    FakeMail mail = FakeMail.builder().sender(senderMailAddress).attribute("delivery-error", "Delivery error").mimeMessage(mimeMessage).name(MAILET_NAME).recipient(new MailAddress("recipient@domain.com")).lastUpdated(DateTime.parse("2016-09-08T14:25:52.000Z").toDate()).build();
    dsnBounce.service(mail);
    String hostname = InetAddress.getLocalHost().getHostName();
    String expectedContent = "Hi. This is the James mail server at " + hostname + ".\nI'm afraid I wasn't able to deliver your message to the following addresses.\nThis is a permanent error; I've given up. Sorry it didn't work out.  Below\nI include the list of recipients and the reason why I was unable to deliver\nyour message.\n\n" + "Failed recipient(s):\n" + "recipient@domain.com\n" + "\n" + "Error message:\n" + "Delivery error\n" + "\n";
    List<SentMail> sentMails = fakeMailContext.getSentMails();
    assertThat(sentMails).hasSize(1);
    SentMail sentMail = sentMails.get(0);
    MimeMessage sentMessage = sentMail.getMsg();
    MimeMultipartReport content = (MimeMultipartReport) sentMessage.getContent();
    BodyPart bodyPart = content.getBodyPart(0);
    assertThat(bodyPart.getContentType()).isEqualTo("text/plain; charset=us-ascii");
    assertThat(bodyPart.getContent()).isEqualTo(expectedContent);
