    MessageAttachment attachment = MessageAttachment.builder().attachment(org.apache.james.mailbox.model.Attachment.builder().attachmentId(AttachmentId.from("blodId")).bytes(text.getBytes()).type(expectedMimeType).build()).cid(Cid.from(expectedCID)).isInline(true).build();
