    List<ProtocolResponse> responses = testee.handle(AuthenticatedProtocolRequest.decorate(ProtocolRequest.deserialize(nodes), mockHttpServletRequest)).collect(Collectors.toList());
    assertThat(responses).hasSize(1).extracting(x -> x.getResults().findValue("id").asText(), x -> x.getResults().findValue("name").asText(), x -> x.getResults().findValue("message").asText()).containsExactly(tuple("testId", "testName", "works"));
