    String outboxId = getOutboxId(accessToken);
    String requestBody = "[" + "  [" + "    \"setMessages\"," + "    {" + "      \"create\": { \"" + messageCreationId + "\" : {" + "        \"from\": { \"name\": \"Me\", \"email\": \"" + fromAddress + "\"}," + "        \"to\": [{ \"name\": \"BOB\", \"email\": \"someone@example.com\"}]," + "        \"subject\": \"" + messageSubject + "\"," + "        \"textBody\": \"Hello someone, and thank you for joining example.com!\"," + "        \"mailboxIds\": [\"" + outboxId + "\"]" + "      }}" + "    }," + "    \"#0\"" + "  ]" + "]";
    List<MailboxListener.Event> events = Lists.newArrayList();
    jmapServer.getJmapProbe().addMailboxListener(new MailboxListener() {

        @Override
        public ListenerType getType() {
            return ListenerType.ONCE;
        }

        @Override
        public ExecutionMode getExecutionMode() {
            return ExecutionMode.SYNCHRONOUS;
        }

        @Override
        public void event(Event event) {
            events.add(event);
        }
    });
    String messageId = with().header("Authorization", accessToken.serialize()).body(requestBody).// When
    post("/jmap").then().extract().body().<String>path(ARGUMENTS + ".created." + messageCreationId + ".id");
    calmlyAwait.atMost(5, TimeUnit.SECONDS).until(() -> events.stream().anyMatch(event -> isAddedToOutboxEvent(messageId, event)));
}

